(12, 25, NULL, 'Steinberg Cubase Pro 14 v14.0.20 WiN', 'steinberg-cubase-pro-14-v14-0-20-win', '<pre>Do you want to start creating your own music, take your courseion to a professional level, or optimize your workflow in a short time? Whatever you need, Cubase will help you reach your full creative potential.</pre>', 3900.00, 'zip', '', 'https://drive.google.com/file/d/15iNyRNCWrPsFMKGS-0MRqKOl3JEbQ6BE/view?usp=sharing', 'uploads/thumbnails/68a20a0e5a8de_maxresdefault.webp', 'Commercial', '1.0 GB', 'AK23STUDIOKITS', 'www.downloads.ak23studiokits.com', NULL, NULL, NULL, 1, 0, '2025-08-17 13:57:50', '2025-09-19 04:08:04', NULL),
(13, 25, NULL, 'Steinberg  Cubase 5 Pro full version', 'steinberg-cubase-5-pro-full-version', '<pre>Steinberg Cubase 5 PRO v5.1.0.105 Full version - With millions of musicians, producers and sound engineers around the world &nbsp;using Cubase every day, Cubase is one of the most popular digital audio &nbsp;workstations of our time. Due to its pristine sound quality, intuitive &nbsp;handling and unrivaled range of advanced tools, Cubase is not only &nbsp;considered by many users as the most complete DAW on the market today, &nbsp;but also sets the benchmark for contemporary music courseion software.</pre>\r\n<h2>&nbsp;</h2>\r\n<div class=\"fa fa-check-square-o\">&nbsp;<strong>Pro editing</strong></div>\r\n<p>The &nbsp;many top-of-the-line tools that come with Cubase Pro let you edit and &nbsp;enhance your recordings in the most convenient and efficient way. Edit &nbsp;multiple tracks at once with the smart Track Edit Groups, quantize your &nbsp;recordings with the straight-forward AudioWarp tool set and push your &nbsp;vocal and monophonic audio recordings to perfection with the stunning &nbsp;VariAudio 2.0 audio editing and pitch alteration tool.</p>\r\n<div class=\"fa fa-check-square-o\">&nbsp;<strong>State-of-the-art mixing</strong></div>\r\n<p>The &nbsp;state-of-the-art mixing environment in Cubase Pro is unmatched in terms &nbsp;of flexibility, quality and workflow. VCA faders and Control Link &nbsp;Groups let you master even complex mixing situations. The 5.1 surround &nbsp;support makes Cubase Pro the first choice in many film studios &nbsp;worldwide. The powerful Control Room concept seamlessly integrates &nbsp;performer mixes and monitoring setups into your recording and mixing &nbsp;workflow. The list just goes on and on.</p>\r\n<p>&nbsp;</p>', 2900.00, 'zip', '', 'https://drive.google.com/file/d/1Cz_5X30BLP1adUO2-OhYV0weTufE4Oqq/view?usp=sharing', 'uploads/thumbnails/68bc2a809701f_cubase-5-crack.jpeg', 'Commercial', '2.5 GB', 'AK23STUDIOKITS', 'www.downloads.ak23studiokits.com', '', '', '', 1, 1, '2025-09-06 09:35:12', '2025-10-11 12:35:14', NULL),
(14, 34, NULL, 'Mixed Feelings - Afrobeats Hits', 'mixed-feelings-afrobeats-hits', '<p class=\"lead\">\'Mixed Feelings\' by Mykah is an Afro sample pack loaded with 756 MB of content, including 145 WAV loops. Offering a must-have toolkit for creating Afro-inspired hits, from rhythmic percussion to melodic elements. Whether you\'re producing Afrobeat, Afrohouse, or any other Afro-influenced genre. Having access to these samples will greatly enhance the creative process and allow producers to craft unique Afro-inspired hits.</p>\r\n<p>&bull; 145 WAV Loops (Including Drums, Melodics, Vox)<br>&bull; 44.1kHz/24-Bit WAV Quality<br>&bull; 100% Royalty-Free<br>&bull; Key &amp; Tempo Labelled</p>', 4900.00, 'zip', '', 'https://drive.google.com/file/d/1Nm53XQk2XrrFukB4D-TsU88hstqLDFH9/view?usp=sharing', 'uploads/thumbnails/68cdbe5acc361_MixedFeelingsAfrobeatsHitscover.webp', 'Commercial', '172 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/66288/Mixed%20Feelings%20-%20Afrobeats%20Hits%20demo.mp3', 'https://www.producerloops.com/Download-Mykah-Mixed-Feelings--Afrobeats-Hits.html', 1, 0, '2025-09-19 17:34:34', '2025-10-14 12:08:36', NULL),
(15, 36, NULL, 'QUEEN – Amapiano Beats', 'queen-amapiano-beats', '<p><span style=\"color: #993300;\"><strong>course Details:</strong></span><br>&bull; 99 WAV Loops (Including Drums, Melodics, Vocals, and FXs)<br>&bull; 47 MIDI Files<br>&bull; 44.1 kHz / 24-Bit WAV Quality<br>&bull; Key &amp; Tempo Labelled<br>&bull; 100% Royalty-Free</p>\r\n<p>\'QUEEN\' is an Amapiano Pack loaded with 307MB of content, including 99 WAV Loops and 47 MIDI Files. Perfect for producers looking to create smashing Amapiano tracks that get people dancing. This new collection offers the essentials to craft authentic and high-quality Amapiano jams, A great choice for anyone wanting to dive into Amapiano courseion or add fresh sounds to their libraries.</p>', 6500.00, 'zip', '', 'https://drive.google.com/file/d/1CRB2eS7BcXHMzAD4HHEu8jfB6wlBiVsq/view?usp=sharing', 'uploads/thumbnails/68cf970b21d05_Queen_CoverArt.webp', 'Commercial', '126 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/63565/Queen%20%20%20Amapiano%20Beats%20DemoTrack.mp3', 'https://www.producerloops.com/Download-Aotbb-QUEEN-Amapiano-Beats.html', 1, 0, '2025-09-21 03:11:23', '2025-10-14 12:06:46', NULL),
(16, 35, NULL, 'Candy Store Amapiano', 'candy-store-amapiano', '<h3><strong>course DETAILS:</strong></h3>\r\n<p><strong>155 WAV Loops</strong>&nbsp;<em><br>38 Basses<br>85 Drums &amp; Percussions<br>32 Meldoeis<br>6 Full-Stacks</em></p>\r\n<p>6 Full-Stacks</p>\r\n<p><strong>53 MIDI Files</strong><strong><br></strong><em>Including Melodies &amp; Basses<strong><br></strong></em></p>\r\n<p><em><strong>40&nbsp; Drum One-Shots</strong></em><br><em>9 Snares, Rims, and Claps&nbsp;</em><br><em>11 Percussions&nbsp;</em><br><em>6 Kicks&nbsp;&nbsp;</em><br><em>9 Hi-Hats&nbsp;</em><br><em>5 F Xs</em></p>\r\n<p><strong>44.1 K Hz / 24-Bit Wav Quality</strong><br><strong>Bpm and Key Labeled</strong><br><strong>100% Royalty-Free</strong></p>\r\n<p><strong>Size: 1.11 Gb</strong>&nbsp;<em>(unzipped)</em></p>\r\n<p><em><strong>\'Candy Store\'</strong> by Cable courseion is an All-In-One Sample Pack loaded with<strong> 1.11GB</strong>&nbsp;of content, including <strong>155 WAV Loops, 53 MIDI Files,</strong> and <strong>40 One-Shots</strong>. This exciting collection introduces a fresh set of never-before-heard sounds, offering punchy drums, deep log drums, catchy, melodies, and atmospheric FXs that are perfect for crafting both high-energy dancefloor bangers and smooth, laid-back lounge vibes.</em></p>', 2700.00, 'zip', '', 'https://drive.google.com/file/d/1fV9oZ-XqMa4eUQCpVNTVgTCio45KJ58Z/view?usp=sharing', 'uploads/thumbnails/68d3c4359b330_Candy-Store-amapiano.jpg', 'Commercial', '570 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://producersources.com/wp-content/uploads/2024/11/Candy-Store-amapiano.mp3', 'https://producersources.com/course/candy-store-amapiano-140-loops-mids-one-shots/', 1, 0, '2025-09-24 07:13:09', '2025-10-14 12:02:24', NULL),
(17, 35, NULL, 'Amapiano Maasi', 'amapiano-maasi', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Sample &amp; Loop Kits<br>&bull; 5 WAV Full Mix Demos<br>&bull; 5 MIDI Multi-Track Files Included<br>&bull; All Loops include Dry &amp; Wet Versions<br>&bull; 10 Drum Bus Loops<br>&bull; 10 Kick Loops<br>&bull; 12 Snare Loops<br>&bull; 8 Rim Shot Loops<br>&bull; 2 Clap Loops<br>&bull; 2 Open-Hat Loops<br>&bull; 8 Cymbal Loops<br>&bull; 54 Perc Loops<br>&bull; 14 Log Drum Loops<br>&bull; 86 Synth Loops<br>&bull; 2 Guitar Loops<br>&bull; 2 Vox Loops<br>&bull; 2 Choir Loops<br>&bull; 28 SFX<br>&bull; Loops Synced To BPM<br>&bull; 44.1kHz/24-Bit<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p><strong>\'Amapiano Maasi\' by Mystic Samples is a distinguished Amapiano samples &amp; loops pack encapsulating the energetic and uplifting spirit of Afro-infused music and all its subgenres providing you with all you need to produce your own captivating rhythms inspired by famous artists such as DJ Maphorisa, Kabza De Small, Focalistic, Asake and more.</strong></p>', 3700.00, 'ZIP', '', 'https://drive.google.com/file/d/1abqr2Po0UzTtRpIiQYNCo0IjGcdDj8x5/view?usp=sharing', 'uploads/thumbnails/68d3c9cbc4fe3_Mystic Samples_Amapiano Maasi_1400x1400.webp', 'Commercial', '690 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/64827/Mystic%20Samples%20Amapiano%20Maasi%20Demo.mp3', 'https://www.producerloops.com/Download-Mystic-Samples-Amapiano-Maasi.html', 1, 0, '2025-09-24 07:36:59', '2025-10-14 11:59:31', NULL),
(18, 35, NULL, 'Piano Diego - Amapiano', 'piano-diego-amapiano', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 179 Loops (Including Drums, Melodics)<br>&bull; 44.1kHz/24-Bit WAV Quality<br>&bull; BPM &amp; Key Labelled<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'Piano Diego</strong><strong>\' by Eno Beatzz is a sample pack loaded with 179 WAV loops, containing high-quality sounds that will help you start producing your next Amapiano Jam! This pack will provide you with must-have samples to help you produce your next hit track, including drums, percussions, basses, log drums, melodies, chords, keys, guitars and more.</strong></p>\r\n<p>Everything has been carefully mixed and EQ\'d for maximal usability and impact. You can even edit and chop the loops to make them unique. Drop the samples in your DAW or your favorite sampler, including Logic, GarageBand, Soundtrack, Digital Performer, Sony Acid, Ableton Live, Adobe Audition, Cakewalk Sonar, Pro Tools, Emagic EXS24, and many more.</p>\r\n<p>And, of course, all loops &amp; samples are 100% royalty-free!</p>', 4800.00, 'ZIP', '', 'https://drive.google.com/file/d/16c-fje17Jl8uwUcfOqtsh3FEEDgYiFGU/view?usp=sharing', 'uploads/thumbnails/68ee3c4dc8d14_PIANO DIEGO – Amapiano cover.webp', 'Commercial', '155 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/64262/PIANO%20DIEGO%20%E2%80%93%20Amapiano%20demo.mp3', 'https://www.producerloops.com/Download-Eno-Beatzz-Piano-Diego--Amapiano.html', 1, 0, '2025-09-24 07:46:24', '2025-10-14 12:04:29', NULL),
(19, 35, NULL, 'QUEEN 4 - Amapiano Beats', 'queen-4-amapiano-beats', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 85 Loops (Including Drums, Melodics, Vocals)<br>&bull; 47 MIDI Files<br>&bull; 44.1kHz/24-Bit WAV Quality<br>&bull; BPM &amp; Key Labelled<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'QUEEN 4\' is an Amapiano sample pack loaded with 85 WAV loops and 47 MIDI files. Perfect for producers looking to create smashing Amapiano tracks that get people dancing. This new collection offers the essentials to craft authentic and high-quality Amapiano jam, a great choice for anyone wanting to dive into Amapiano courseion or add fresh sounds to their libraries. This pack is a great choice for anyone looking to dive into Amapiano courseion or add fresh sounds to your collection!</strong></p>\r\n<p>Featuring an array of expertly crafted sounds and tools including:</p>\r\n<p><strong>WAV Loops:</strong> Offering you must-have samples to produce your next hit tracks, including drums, percussions, basses, log drums, melodies, chords, keys, pianos, rhodes, leads, synths, saxes, pads, flutes, plucks, arps, vocals and more.</p>', 5900.00, 'ZIP', '', 'https://drive.google.com/file/d/1Qqog0LeS5sCv76eeYNCkI1XTXBqtbwDg/view?usp=sharing', 'uploads/thumbnails/68d3cd4da76a2_QUEEN4_CoverArt.webp', 'Commercial', '79 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/64485/QUEEN4%20Demotrack.mp3', 'https://www.producerloops.com/Download-Aotbb-QUEEN-4--Amapiano-Beats.html', 1, 0, '2025-09-24 07:51:57', '2025-10-14 11:55:13', NULL),
