(48, 35, NULL, 'Expensive Taste Amapiano', 'expensive-taste-amapiano', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 124 Loops (Including Drums, Melodics, Vocals, FX)<br>&bull; 39 MIDI Files<br>&bull; 46 One-Shots<br>&bull; 44.1kHz/24-Bit WAV Quality<br>&bull; BPM &amp; Key Labelled<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'Expensive Taste Amapiano\' by Crazy Beats is an All-In-One sample pack loaded with 124 WAV loops, 39 MIDI files and 46 one-shots. This unique sample pack is equipped with the essential sounds and materials needed to create smashing Amapiano records! This pack will provide you with must-have samples to help you produce your next hit track, including drums, percussions, log drums, basses, melodies, chords, pianos, leads, keys, guitars, saxes, pads, vocals, FX and more.</strong></p>\r\n<p>MIDI files are included so you can control your project thoroughly. The MIDI files allow you to apply the melodies to any sound. Alternatively, drag and drop the WAV files into your DAW of choice to get started on your next track.</p>', 3900.00, 'ZIP', '', 'https://drive.google.com/file/d/159B0uQZruU15jue_chS2XAO9LaCEk0DX/view?usp=sharing', 'uploads/thumbnails/68d6427810f91_Expensive Taste Amapiano cover.webp', 'Commercial', '608 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/64354/Expensive%20Taste%20Amapiano%20demo.mp3', 'https://www.producerloops.com/Download-Crazy-Beats-Expensive-Taste-Amapiano.html', 1, 0, '2025-09-26 04:36:24', '2025-10-10 12:43:49', NULL),
(49, 35, NULL, 'Amapiano Yebo', 'amapiano-yebo', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Samples &amp; Loops Kits<br>&bull; 5 WAV Full Mixes Demos<br>&bull; 5 Multi-Track MIDI Files Included<br>&bull; All Loops include Dry &amp; Wet Versions<br>&bull; 10 Drum Bus Loops<br>&bull; 6 Kick Loops<br>&bull; 34 Snare Loops<br>&bull; 12 Clap Loops<br>&bull; 4 Hi-Hat Loops<br>&bull; 10 Cymbal Loops<br>&bull; 56 Perc Loops<br>&bull; 4 Bass 808 Loops<br>&bull; 20 Log Drum Loops<br>&bull; 96 Synth Loops<br>&bull; 4 Flute Loops<br>&bull; 2 Guitar Loops<br>&bull; 2 Sound FXs<br>&bull; Loops Synced To BPM<br>&bull; 44.1 kHz/24-Bit<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p class=\"lead\"><strong>\'Amapiano YEBO\' by Mystic Samples kicks off this body-moving series of Amapiano bringing everything you need to create groovy and captivating upbeat rhythms inspired by famous artists such as DJ Maphorisa, Kabza De Small, Focalistic and more.</strong></p>\r\n<p>Inside you\'ll find a range of vibrant High Quality WAV Samples &amp; Loops passionately crafted by Kryptic featuring Synth Loops : Pluck, Key, Lead, Organ, Seq, Bass, Strings, Gate, Poly, Arp &amp; Brass, Flute loops, Guitar loops, Sound Fxs, Log Drums loops, thumping drum loops and Multi-Track MIDI files</p>\r\n<p>&nbsp;</p>', 3600.00, 'ZIP', '', 'https://drive.google.com/file/d/1G8bvYVMDQdm3zfSS0RpLnNcCfVK6x07F/view?usp=sharing', 'uploads/thumbnails/68d6435f099a5_Mystic Samples_Amapiano Yebo_1400x1400.webp', 'Commercial', '761 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/63165/Mystic%20Samples%20Amapiano%20Yebo%20Demo.mp3', 'https://www.producerloops.com/Download-Mystic-Samples-AMAPIANO-YEBO.html', 1, 0, '2025-09-26 04:40:15', '2025-10-10 12:31:55', NULL),
(50, 35, NULL, 'Amapiano: Inkosi', 'amapiano-inkosi', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Samples &amp; Loops Kits<br>&bull; 5 WAV Full Mixes Demos<br>&bull; 5 MIDI Files Included<br>&bull; All Loops include Dry &amp; Wet Versions<br>&bull; 10 Drum Loops<br>&bull; 10 Kick Loops<br>&bull; 18 Snare Loops<br>&bull; 10 Rim Shot Loops<br>&bull; 16 Clap Loops<br>&bull; 2 Hi-Hat Loops<br>&bull; 2 Open-Hat Loops<br>&bull; 4 Cymbal Loops<br>&bull; 52 Perc Loops<br>&bull; 20 Log Drum Loops<br>&bull; 2 Bass 808 Loops<br>&bull; 102 Synth Loops<br>&bull; 2 Piano Loops<br>&bull; 4 Guitar Loops<br>&bull; 6 Flute Loops<br>&bull; 6 Vox Loops<br>&bull; 88 Sound FXs<br>&bull; 44.1 kHz/24-Bit<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p class=\"lead\"><strong>\'Amapiano Inkosi\' by Mystic Samples is a new trailblazer sound pack in this real body-shaking Amapiano samples collection straight from Soweto delivered directly to your favorite DAW with a single Drag &amp; Drop move.</strong></p>\r\n<p>This sample pack comes loaded with 5 blistering Samples &amp; Loops Kits created with tracks in mind from famous artists such as Costa Titch, Davido, Focalistic, DJ Maphorisa, Asake, Burna Boy, Kabza De Small and more featuring High Quality WAV Samples &amp; Loops including Synth loops, Piano loops, Guitar loops, Flute loops, Brass loops, Vox loops, Sound Fxs loops, flipped-out Log Drum loops, 808 Bass loops, Perc Loops, Drum loops and bass loops.</p>', 4600.00, 'ZIP', '', 'https://drive.google.com/file/d/1-VdOcdcf1SpaYesVNL470uzeycCsLgNX/view?usp=sharing', 'uploads/thumbnails/68d6635e0d259_Mystic Samples_Amapiano Inkosi_1400x1400.webp', 'Commercial', '1.07 GB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/60466/Mystic%20Samples%20Amapiano%20Inkosi%20Demo.mp3', 'https://www.producerloops.com/Download-Mystic-Samples-AMAPIANO-INKOSI.html', 1, 0, '2025-09-26 06:56:46', '2025-10-10 12:29:41', NULL),
(51, 35, NULL, 'Kryptic Amapiano Collection Vol 1', 'kryptic-amapiano-collection-vol-1', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Construction Kits<br>&bull; 5 WAV Full Mixes Demos<br>&bull; 5 MIDI Files Included<br>&bull; All Loops include Dry &amp; Wet Versions<br>&bull; 20 Ethnic Drum Loops<br>&bull; 14 Log Drum Loops<br>&bull; 14 Kick Loops<br>&bull; 16 Snare Loops<br>&bull; 6 Clap Loops<br>&bull; 2 Hi-Hat Loops<br>&bull; 2 Cymbal Loops<br>&bull; 28 Perc Loops<br>&bull; 8 Bass 808 Loops<br>&bull; 2 Bass Loops<br>&bull; 48 Synth Loops<br>&bull; 10 Ethnic Instrument Loops<br>&bull; 8 Toy Instrument Loops<br>&bull; 2 Electric Piano Loops<br>&bull; 2 Saxophone Loops<br>&bull; 2 Flute Loops<br>&bull; 2 Strings Loops<br>&bull; 8 Vox Loops<br>&bull; 32 Sound FXs<br>&bull; 44.1 kHz/24-Bit<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p class=\"lead\"><strong>\'Kryptic Amapiano Collection Vol.1\' from Kryptic blows in this flaming &amp; groovy Amapiano series hailing from South Africa providing you with mind-blowing samples &amp; loops for your next Amapiano chart-buster Hits wrapped up with the real body-shaking magic.</strong></p>\r\n<p>This pack is loaded with 5 spanking Samples &amp; Loops Kits inspired by famous artists such as Davido, Focalistic, DJ Maphorisa, Asake, Burna Boy, Major League DJz, Lady Du, Kabza De Small and more featuring High Quality WAV Samples &amp; Loops including Synth loops, Ethnic Instruments loops: Ngoni Donso, Balafon and Requinto, Electric Piano, Saxophone, Flute and String loops, Cavaquinho, Flex-A-Tone and Friggered Trumpet loops, Vox loops, Sound Fxs, Log Drums, Ethnic Drum loops and bass loops.</p>', 7200.00, 'ZIP', '', 'https://drive.google.com/file/d/1ruF_HBS0GwK7d4Tk40Cd9Xsdn5TqQIt2/view?usp=sharing', 'uploads/thumbnails/68d664800c218_Aetheric Samples_Kryptic Amapiano Collection Vol.1_1000x1000.webp', 'Commercial', '559 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/57934/Aeth