(52, 35, NULL, 'Amapiano: Giza', 'amapiano-giza', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Samples &amp; Loops Kits<br>&bull; 5 WAV Full Mixes Demos<br>&bull; 5 MIDI Files Included<br>&bull; All Loops include Dry &amp; Wet Versions<br>&bull; 10 Drum Loops<br>&bull; 10 Kick Loops<br>&bull; 16 Snare Loops<br>&bull; 10 Rim Shot Loops<br>&bull; 6 Clap Loops<br>&bull; 14 Hi-Hat Loops<br>&bull; 2 Open-Hat Loops<br>&bull; 12 Cymbal Loops<br>&bull; 52 Perc Loops<br>&bull; 20 Log Drum Loops<br>&bull; 2 Strings Loops<br>&bull; 88 Synth Loops<br>&bull; 4 Piano Loops<br>&bull; 2 Brass Loops<br>&bull; 2 Choir Loops<br>&bull; 6 Vox Loops<br>&bull; 18 Sound FXs<br>&bull; Loops Synced To BPM<br>&bull; 44.1 kHz/24-Bit<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p class=\"lead\"><strong>\'Amapiano Giza\' by Mystic Samples is another meticulously curated sound pack bursting with creativity and innovation delivered directly to your favorite DAW with a single Drag &amp; Drop move and offering the versality needed to craft your unique Amapiano tracks.</strong></p>\r\n<p>This sample pack pops in into 5 Samples &amp; Loops Kits inspired by famous artists such as DJ Maphorisa, Asake, Burna Boy, Kabza De Small and more encompassing High Quality WAV Samples &amp; Loops including awe-inspiring Synth loops (Arp, Keys, Lead, Pluck, Strings, Bass and much more), Piano loops, Brass loops, Choir loops, Vox loops, Sound Fxs loops, firing Log Drum loops, Perc Loops. Drum loops and more.</p>', 3800.00, 'ZIP', '', 'https://drive.google.com/file/d/1ek-H0WJ4iCrbYTWaoWYQbicUhuZTnTHJ/view?usp=sharing', 'uploads/thumbnails/68d6660d8b7b2_Mystic Samples_Amapiano Giza_1400x1400.webp', 'Commercial', '757 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/62220/Mystic%20Samples%20Amapiano%20Giza%20Demo.mp3', 'https://www.producerloops.com/Download-Mystic-Samples-AMAPIANO-GIZA.html', 1, 0, '2025-09-26 07:08:13', '2025-10-10 07:52:16', NULL),
(53, 35, NULL, 'KUNJANI: Amapiano & Chill', 'kunjani-amapiano-chill', '<div style=\"font-size: 10px; color: #cccccc; line-break: anywhere; word-break: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-family: Interstate,Lucida Grande,Lucida Sans Unicode,Lucida Sans,Garuda,Verdana,Tahoma,sans-serif; font-weight: 100;\">SynthPresets &middot; <a style=\"color: #cccccc; text-decoration: none;\" title=\"AOTBB - KUNJANI: Amapiano &amp; Chill\" href=\"https://soundcloud.com/synthpresets/aotbb-kunjani-amapiano-chill-samples-loops\" target=\"_blank\" rel=\"noopener\">AOTBB - KUNJANI: Amapiano &amp; Chill</a></div>\r\n<p><strong>course Details:</strong></p>\r\n<p>&bull; 152 WAV Loops (Including Drums and Melodics)<br>&bull; 98 MIDI Files<br>&bull; 82 One-Shots<br>&bull; 6 Log Drum Presets (.fst Files)<br>&bull; 44.1 kHz / 24-Bit WAV Quality<br>&bull; Key &amp; Tempo Labelled<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'KUNJANI - Amapiano &amp; Chill\' by AOTBB is an All-In-One Sample Pack loaded with 330+ Files in Total, including 152 WAV Loops, 98 MIDI Files, 82 One-Shots and 6 Log Drum Presets. KUNJANI will supply you with never heard before needed for your next Amapiano Hit Record.</strong></p>\r\n<p>This pack will provide must-have samples to help you produce your next hit track, including Drum Loops, Melody Loops, and Bass Loops.</p>\r\n<p>MIDI files are included so you can control your project completely. The MIDI files allow you to apply the melodies to any sound. Alternatively, Drag and Drop the WAV files into your DAW of choice to get started on your next track.</p>', 4200.00, 'ZIP', '', 'https://drive.google.com/file/d/1siSeSJ-dsQOzLiN9JO6bwSYBNgNTRP7u/view?usp=sharing', 'uploads/thumbnails/68d6677c1b0a8_KUNJANI Artcover.webp', 'Commercial', '240 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/58017/KUNJANI%20DemoTrack.mp3', 'https://www.producerloops.com/Download-Aotbb-KUNJANI-Amapiano-Chill.html', 1, 0, '2025-09-26 07:14:20', '2025-10-08 13:10:29', NULL),
(54, 35, NULL, 'Pretoria - Amapiano', 'pretoria-amapiano', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 222 WAV Loops<br>&bull; 108 MIDI Files<br>&bull; 159 One-Shots</p>\r\n<p class=\"lead\"><strong>\'PRETORIA - AMAPIANO\' is an All-In-One Sample Pack loaded with 480+ Files in Total, including 222 WAV Loops, 108 MIDI Files, 159 One-Shots, and bringing you the ultimate tools to join the Amapiano Trending Wave!</strong></p>\r\n<p>Amapiano was birthed in the heart of South Africa by the likes of Kabza De Smallz, DJ Maphorisa, Virgo Deep, Lady Du, Focalistic, DJ Major League, and many more. Since early 2020 this type of music found its way to Nigeria and has been making waves in West Africa.</p>\r\n<p>We included MIDI Files to give you complete control over your project. The MIDI Files allow you to apply the melodies to any sound. Alternatively, Drag and Drop the WAV files into your DAW of choice to get started on your next track.</p>', 4500.00, 'ZIP', '', 'https://drive.google.com/file/d/18tPH6vrdJWK9JQrbF22iPS7-uaTgtnhF/view?usp=sharing', 'uploads/thumbnails/68d66f0d75e56_PRETORIA.webp', 'Commercial', '162 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/55196/DEMO%20TRACK.mp3', 'https://www.producerloops.com/Download-Aotbb-PRETORIA--AMAPIANO.html', 1, 0, '2025-09-26 07:46:37', '2025-10-08 13:07:04', NULL),
(55, 35, NULL, 'Amapiano Hitmaker 3', 'amapiano-hitmaker-3', '<div class=\"course-details clearfix\">\r\n<ul>\r\n<li>\r\n<div>1.43 GB</div>\r\n</li>\r\n<li>\r\n<div>24-Bit Samples</div>\r\n</li>\r\n<li>\r\n<div>50 Bass Loops</div>\r\n</li>\r\n<li>\r\n<div>52 Synth Loops</div>\r\n</li>\r\n<li>\r\n<div>40 Full Drum Loops</div>\r\n</li>\r\n<li>\r\n<div>40 Top Drum Loops</div>\r\n</li>\r\n<li>\r\n<div>20 Shaker Loops</div>\r\n</li>\r\n<li>\r\n<div>32 Percussion Loops</div>\r\n</li>\r\n<li>\r\n<div>20 Drum Fills</div>\r\n</li>\r\n<li>\r\n<div>24 Song Vocals (12 Dry &amp; 12 Wet)</div>\r\n</li>\r\n<li>\r\n<div>22 Vocal Chops &amp; Chants</div>\r\n</li>\r\n<li>\r\n<div>81 Effects</div>\r\n</li>\r\n<li>\r\n<div>150 Total One-Shots</div>\r\n</li>\r\n<li>\r\n<div>20 Crash One-Shots</div>\r\n</li>\r\n<li>\r\n<div>20 Hat One-Shots</div>\r\n</li>\r\n<li>\r\n<div>20 Kick One-Shots</div>\r\n</li>\r\n<li>\r\n<div>50 Percussion One-Shots</div>\r\n</li>\r\n<li>\r\n<div>20 Shaker One-Shots</div>\r\n</li>\r\n<li>\r\n<div>20 Snare One-Shots</div>\r\n</li>\r\n<li>\r\n<div>101 MIDI Files</div>\r\n</li>\r\n<li>\r\n<div>10 Sampler Patches (EXS24, Kontakt 2+, NNXT)</div>\r\n</li>\r\n<li>\r\n<div>+ Promo &amp; Discount Folder</div>\r\n</li>\r\n</ul>\r\n<p>Singomakers are back with volume 3 of <em>Amapiano Hitmaker</em>! An inspiring sample pack full of catchy melodies, percussive basslines, gentle drums, and the icing on the cake - incredible vocal hooks, chops, and chants!</p>\r\n<p>This distinctive sound from South Africa continues to make waves. The Singomakers team created this sample pack with tracks in mind from artists such as Goya Menor &amp; Nektunez, Kabza De Small, DJ Maphorisa, Busta 929, Young Stunna, De Mthuda, Major League DJz, Lady Du, Boohle, Nkosazana Daughter, Mellow &amp; Sleazy, Dinaledi, and Mpura.</p>\r\n</div>', 9800.00, 'ZIP', '', 'https://drive.google.com/file/d/17X5ZT3J-0ZdX0d-aD5KFK9NBoD4a9fY3/view?usp=sharing', 'uploads/thumbnails/68d679932dd22_Singomakers_Amapiano_Hitmaker_3_Banner.jpg', 'Commercial', '1.43 GB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://demos.loopmasters.com/16550%2FSM_AH3_DEMO.mp3', 'https://www.loopmasters.com/genres/184-Amapiano/courses/16550-Amapiano-Hitmaker-3', 1, 0, '2025-09-26 08:31:31', '2025-10-08 13:00:18', NULL),
(56, 35, NULL, 'On Repeat - Amapiano', 'on-repeat-amapiano', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Mixed &amp; Mastered Demos<br>&bull; 113&nbsp;Drum &amp; Melody Loops<br>&bull; 74&nbsp;MIDI Files<br>&bull; 35 One-Shots<br>&bull; Key &amp; Tempo Labelled<br>&bull; 24-Bit WAV<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'On Repeat &ndash; Amapiano\' by Jungle Loops&nbsp;is a new sample pack loaded with 113&nbsp;WAV Loops, 74 MIDI Files and 35 One-Shots&nbsp;crafted with&nbsp;rhythmic drums, catchy melodies and dreamy sounds to make the next AMAPIANO Hits.</strong></p>\r\n<p>This pack will provide must-have samples to help you produce your next hit track, including Melody Loops, Drum Loops, Perc Loops, Bass Loops, Rolls, and SFX.</p>\r\n<p>Included are MIDI Files to give you complete control over your project. The MIDI Files allow you to apply the melodies to any sound. Alternatively, Drag and Drop the WAV files into your DAW of choice to get started on your next track.</p>\r\n<p>Also, you\'ll find One-Shots, allowing you to create new beats, fills, and loops to complement the existing material. Load them up into your sampler of choice and create an infinite number of Drum Loops.</p>', 2900.00, 'ZIP', '', 'https://drive.google.com/file/d/1Rp6I971D7_6v76a-ibXK0x72c5zFfsPP/view?usp=sharing', 'uploads/thumbnails/68d67b4c44a18_Jungle Loops_On Repeat Amapiano_cover.webp', 'Commercial', '141 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/56313/Jungle%20Loops%20On%20Repeat%20Amapiano%20demo.mp3', 'https://www.producerloops.com/Download-Jungle-Loops-On-Repeat--Amapiano.html?srsltid=AfmBOopq_5kzRdS9fIhbo8FKjdxqg7PDsQwMf9CM9EY_4sNFwA4ZRwXs', 1, 0, '2025-09-26 08:38:52', '2025-10-08 12:53:40', NULL),
(57, 34, NULL, 'Afrolover - Afrobeats', 'afrolover-afrobeats', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Mixed &amp; Mastered Demos<br>&bull; 54 Melody and Drum Loops<br>&bull; 34 MIDI Files<br>&bull; 33 Afrobeat WAV One Shots<br>&bull; Key &amp; Tempo Labeled<br>&bull; WAV 24bit / HQ<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'Afrolover - Afrobeats\' by Godlike Loops is equipped with the essential sounds and materials needed to create that smashing Afrobeat records. It comes with 145+ Files, including 54 Melody &amp; Drum WAV Loops, 33 Drums &amp; Fx One-Shots , and 34 MIDI Files inspired byCkay, Wizkid, Burna Boy, 1da Banton, Kizz Daniel, Tiwa Sawage, L.A.X and more...</strong></p>\r\n<p>This pack will provide you with must-have samples to help you produce your next hit track including Electric Guitars, Keys, Violins, Saxes, Basses, Kick Loops, Snare &amp; Rim Loops, Shaker Loops, Various Perc Loops, Full / Top Drum Loops, MIDI loops and Drums &amp; Bass &amp; Fx One Shots.</p>\r\n<p>MIDI files are included, so you can rework all the elements to fit into any project.</p>\r\n<p>LIVE GUITARS DO NOT CONTAIN MIDI FILES</p>\r\n<p>And of course, all loops &amp; samples are 100% Royalty-Free!</p>', 4500.00, 'ZIP', '', 'https://drive.google.com/file/d/1Al_WQ1qwKdG8tCx2F46QLet6W8RKh1N8/view?usp=sharing', 'uploads/thumbnails/68d7bb8a6c141_Afrolover Artwork.webp', 'Commercial', '157', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/62708/Afrolover%20Demo.mp3', 'https://www.producerloops.com/Download-Godlike-Loops-Afrolover--Afrobeats.html', 1, 0, '2025-09-27 07:25:14', '2025-10-09 04:42:16', NULL),
(58, 34, NULL, 'Mahaba Afrobeat Sample Pack', 'mahaba-afrobeat-sample-pack', '<p><iframe src=\"https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/soundcloud%253Atracks%253A1840855782&amp;color=%23ff5500&amp;auto_play=false&amp;hide_related=false&amp;show_comments=true&amp;show_user=true&amp;show_reposts=false&amp;show_teaser=true\" frameborder=\"no\" scrolling=\"no\" width=\"100%\" height=\"166\" allow=\"autoplay\"></iframe></p>\r\n<div style=\"font-size: 10px; color: #cccccc; line-break: anywhere; word-break: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-family: Interstate,Lucida Grande,Lucida Sans Unicode,Lucida Sans,Garuda,Verdana,Tahoma,sans-serif; font-weight: 100;\"><a style=\"color: #cccccc; text-decoration: none;\" title=\"Afrobeat Producers\" href=\"https://soundcloud.com/afrobeat-producers\" target=\"_blank\" rel=\"noopener\">Afrobeat Producers</a> &middot; <a style=\"color: #cccccc; text-decoration: none;\" title=\"Mahaba Afrobeat Sample Pack - Preview\" href=\"https://soundcloud.com/afrobeat-producers/mahaba-afrobeat-sample-pack-preview\" target=\"_blank\" rel=\"noopener\">Mahaba Afrobeat Sample Pack - Preview</a></div>\r\n<div style=\"font-size: 10px; color: #cccccc; line-break: anywhere; word-break: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-family: Interstate,Lucida Grande,Lucida Sans Unicode,Lucida Sans,Garuda,Verdana,Tahoma,sans-serif; font-weight: 100;\">\r\n<div class=\"sub-title\">Radio Ready Afrobeat Commercial Sounds</div>\r\n<div class=\"description\"><strong>\\</strong></div>\r\n<div class=\"description\">\r\n<ul>\r\n<li>23 Drum loops</li>\r\n<li>21 Melody Loops + Stems + MIDI Files&nbsp;</li>\r\n<li>22 Vox loops</li>\r\n<li>16 Guitar loops</li>\r\n<li>7 Rolls and Fills</li>\r\n</ul>\r\n<p>High Quality Wav Sounds&nbsp;</p>\r\n<p>100% Royalty Free&nbsp;</p>\r\n</div>\r\n</div>', 3900.00, 'ZIP', '', 'https://drive.google.com/file/d/1t74_SKk5B_T7ow-4INiiL0cV56