(59, 34, NULL, 'Afriloco: Afrobeats Vol 3', 'afriloco-afrobeats-vol-3', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 190+ Loops (Including Drums &amp; Melodics)<br>&bull; 130+ MIDI Files (Including Melodies, Bass &amp; Drum Patterns)<br>&bull; 110+ Drum One-Shots</p>\r\n<p class=\"lead\"><strong>\'Afriloco - Afrobeats Vol 3\' by ASHKA is the third installment of this Afrobeats series, crafted with groovy drums and dreamy wavy sounds. It comes with 190+ Loops, 130+ MIDI Files and 110+ Drum One-Shots, inspired by the sounds of the African New Wave from Nigeria, Senegal &amp; Morocco the likes of Wizkid, Burnaboy, Davido, Yemi Alade, D Banj and more.</strong></p>\r\n<p>This pack is an innovative piece of today\'s trending Afrobeats &amp; Dancehall vibes with a Moroccan extra touch. You will receive all sounds separated as drums, percussions and instruments, in addition to all MIDI Patterns, composed at a professional level to instantly step up your courseion!</p>', 4800.00, 'ZIP', '', 'https://drive.google.com/file/d/1FjtlOOO0HCEol_UoOBtt972AxDFFp2S0/view?usp=sharing', 'uploads/thumbnails/68d7db827339b_WhatsApp Image 2021-12-13 at 3.46.27 PM.webp', 'Commercial', '126 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/54954/DemoTrack.mp3', 'https://www.producerloops.com/Download-Aotbb-Afriloco-Afrobeats-Vol-3.html', 1, 0, '2025-09-27 09:41:38', '2025-10-09 04:47:21', NULL),
(60, 34, NULL, 'Soso Afrobeats 2023', 'soso-afrobeats-2023', '<div class=\"samplesMFE-d_flex samplesMFE-flex-d_column samplesMFE-ta_left samplesMFE-pos_relative samplesMFE-w_100%\">\r\n<div class=\"samplesMFE-d_flex samplesMFE-flex-d_column samplesMFE-max-h_105px samplesMFE-cursor_pointer\">\r\n<div class=\"samplesMFE-nbOfLines_2\">\r\n<p class=\"samplesMFE-Paragraph samplesMFE-c_text.medium\">\'Soso Afrobeats 2023\' by Godlike Loops is equipped with the essential sounds and materials needed to create that smashing Afrobeat records. It comes with 150+ Files, including 89 Melody &amp; Drum WAV Loops, inspired by Ckay, Wizkid, Burna Boy, 1da Banton, Kizz Daniel, Tiwa Sawage, L.A.X and more... This pack will provide you with must-have samples to help you produce your next hit track including Dry &amp; Wet Electric Guitars, Leads, Trumpets, Pads, Log Drums, Basses, Kick Loops, Snare &amp; Rim Loops, Shaker Loops, Various Perc Loops, Full / Top Drum Loop</p>\r\n</div>\r\n</div>\r\n</div>', 1000.00, 'ZIP', '', 'https://drive.google.com/file/d/1KCc280-9KpqxYon3U-TemwYXmSPe__o5/view?usp=sharing', 'uploads/thumbnails/68d7e65ee8c9c_Soso-Afrobeats-2023-WAV-FANTASTiC-MaGeSY.webp', 'Commercial', '208', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/58558/Soso%20Afrobeats%202023%20Demo.mp3', 'https://www.producerloops.com/Download-Godlike-Loops-Soso--Afrobeats-2023.html?srsltid=AfmBOopYpSMRnYWfYVo4quK-F0I0IUkmmaWDYEAxcI3OAvzIbDbHlU5l', 1, 0, '2025-09-27 10:27:58', '2025-10-09 04:49:26', NULL),
(61, 34, NULL, 'Afrobeats Drummer - Loops & One Shots', 'afrobeats-drummer-loops-one-shots', '<p><strong><iframe src=\"https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/soundcloud%253Atracks%253A1613579838&amp;color=%23ff5500&amp;auto_play=false&amp;hide_related=false&amp;show_comments=true&amp;show_user=true&amp;show_reposts=false&amp;show_teaser=true\" frameborder=\"no\" scrolling=\"no\" width=\"100%\" height=\"166\" allow=\"autoplay\"></iframe></strong></p>\r\n<div style=\"font-size: 10px; color: #cccccc; line-break: anywhere; word-break: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-family: Interstate,Lucida Grande,Lucida Sans Unicode,Lucida Sans,Garuda,Verdana,Tahoma,sans-serif; font-weight: 100;\"><a style=\"color: #cccccc; text-decoration: none;\" title=\"Innovation Sounds\" href=\"https://soundcloud.com/innovationsoundss\" target=\"_blank\" rel=\"noopener\">Innovation Sounds</a> &middot; <a style=\"color: #cccccc; text-decoration: none;\" title=\"Afrobeats Drummer - Loops &amp; One Shots\" href=\"https://soundcloud.com/innovationsoundss/afrobeats-drummer-loops-one-shots\" target=\"_blank\" rel=\"noopener\">Afrobeats Drummer - Loops &amp; One Shots</a></div>\r\n<p><strong>course Details:</strong></p>\r\n<p>&bull; 30+ Loops (Drum &amp; Percussion)<br>&bull; 50 808s, Bass &amp; Kicks<br>&bull; 55 Claps &amp; Snares<br>&bull; 40+ H-Hats &amp; O-Hats<br>&bull; 55+ Percussions &amp; Shakers<br>&bull; 30 FX &amp; Others<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'Afrobeats Drummer - Loops &amp; One Shots\' by Ashka contains 200+ Drum One-Shots and 30+ Drums &amp; Percussion Loops, inspired by the most known Afrobeat Stars such as, Wizkid, Rema, Dbanj, Davido and many more.</strong></p>\r\n<p>The Drum kit contains the secret sauce for bouncy and professional Afrobeat drums. It contains high quality Loops &amp; One Shot Drums in Afrobeat style including Kicks, Snares, Claps, Hihats, Open Hats, Percussions, FX and more. By having \'Afrobeats Drummer\' added to your DAW library you will never need to search a lot to start making dope trending Afrobeats.</p>\r\n<p>NOTE: The melodies of the demo are not included in the pack, only the drums and percussion are.</p>\r\n<p>&nbsp;</p>', 5800.00, 'ZIP', '', 'https://drive.google.com/file/d/1ETOrxko0nkorIno60J7e87WLJa6xO1zY/view?usp=sharing', 'uploads/thumbnails/68d7e8998e58f_Afrobeats-Drummer-Loops-One-Shots-Ashka-Cover.webp', 'Commercial', '99 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/54620/Afrobeats%20Drummer%20Loops%20One%20Shots%20Ashka%20Demo.mp3', 'https://www.producerloops.com/Download-Aotbb-Afrobeats-Drummer--Loops-One-Shots.html', 1, 0, '2025-09-27 10:37:29', '2025-10-09 04:51:15', NULL),
(62, 34, NULL, 'Banjoko Afrobeats', 'banjoko-afrobeats', '<p><strong><iframe src=\"https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/soundcloud%253Atracks%253A1528546375&amp;color=%23ff5500&amp;auto_play=false&amp;hide_related=false&amp;show_comments=true&amp;show_user=true&amp;show_reposts=false&amp;show_teaser=true\" frameborder=\"no\" scrolling=\"no\" width=\"100%\" height=\"166\" allow=\"autoplay\"></iframe></strong></p>\r\n<div style=\"font-size: 10px; color: #cccccc; line-break: anywhere; word-break: normal; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; font-family: Interstate,Lucida Grande,Lucida Sans Unicode,Lucida Sans,Garuda,Verdana,Tahoma,sans-serif; font-weight: 100;\"><a style=\"color: #cccccc; text-decoration: none;\" title=\"SynthPresets\" href=\"https://soundcloud.com/synthpresets\" target=\"_blank\" rel=\"noopener\">SynthPresets</a> &middot; <a style=\"color: #cccccc; text-decoration: none;\" title=\"Godlike Loops - Banjoko Afrobeats\" href=\"https://soundcloud.com/synthpresets/godlike-loops-banjoko-afrobeats-samples-loops\" target=\"_blank\" rel=\"noopener\">Godlike Loops - Banjoko Afrobeats</a></div>\r\n<p><strong>course Details:</strong></p>\r\n<p>&bull; 5 Mixed &amp; Mastered Demos<br>&bull; 83 Dry &amp; Wet Melody and Drum Loops<br>&bull; 29 MIDI Files<br>&bull; 34 Afrobeat One-Shots (Drum and Bass)<br>&bull; Key &amp; Tempo Labelled<br>&bull; WAV 24bit / HQ<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'Banjoko Afrobeats\' by Godlike Loops x Sean P is equipped with the essential sounds and materials needed to create that smashing Afrobeat records. It comes with 145+ Files, including 83 Melody &amp; Drum WAV Loops, 34 Drums &amp; FX One-Shots, and 29 MIDI Files inspired by Ckay, Wizkid, Burna Boy, 1da Banton, Kizz Daniel, Tiwa Sawage, L.A.X and more...</strong></p>\r\n<p>This pack will provide you with must-have samples to help you produce your next hit track including Electric Guitars, Vocals, Bells, Keys, Log Drums, Basses, Kick Loops, Snare &amp; Rim Loops, Shaker Loops, Various Perc Loops, Full / Top Drum Loops, MIDI loops and Drums &amp; Bass One Shots.</p>\r\n<p>MIDI files are included, so you can rework all the elements to fit into any project.</p>\r\n<p>LIVE GUITARS DO NOT CONTAIN MIDI FILES!</p>\r\n<p>And of course, all loops &amp; samples are 100% Royalty-Free!</p>', 4200.00, 'ZIP', '', 'https://drive.google.com/file/d/12d02Ytz6bLI3bNnVSEhQJk0Bkdnhk3lH/view?usp=sharing', 'uploads/thumbnails/68d7eb588719b_Banjoko Afrobeats Graphic.webp', 'Commercial', '507', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/59415/Banjoko%20Afrobeats%20Demo.mp3', 'https://www.producerloops.com/Download-Godlike-Loops-Banjoko-Afrobeats.html', 1, 0, '2025-09-27 10:49:12', '2025-10-09 05:00:19', NULL);
