(72, 39, NULL, 'Infinity Hip Hop Drums Vol 2', 'infinity-hip-hop-drums-vol-2', '<p style=\"font-stretch: normal; line-height: normal;\"><strong>course Details:</strong><br>&nbsp;</p>\r\n<div>&bull; 71 One-Shots</div>\r\n<div>&bull; 48kHz/24-Bit</div>\r\n<div>&bull; 26 Hi-Hat One-Shots</div>\r\n<div>&bull; 23 Kick One-Shots</div>\r\n<div>&bull; 22 Snare One-Shots</div>\r\n<div>&bull; Includes Soundminer Metadata</div>\r\n<div>&bull; 100% Royalty-Free</div>\r\n<div>\r\n<p class=\"lead\">\'Infinity Hip Hop Drums Vol 2\' by Epic Stock Media includes 71 hypnotic Hip Hop drums, one-shots, crunchy hi-hats, popping snares and all the core essential drum one-shot samples needed for creating Dark Urban drum kits, instrumentals and beats.</p>\r\n<p style=\"font-stretch: normal; line-height: normal;\">&nbsp;</p>\r\n<div>Infinity Hip Hop Drums Vol 2 is the second instalment of the Infinity Drums series. The pack is a cross-genre selection of curated samples and creates unique and professional tracks ranging from the styles like Underground, Trip Hop, Hip Hop, Trap, LoFi, Minimal as well as other Hip Hop or beat-driven genres.</div>\r\n<div>&nbsp;</div>\r\n<div>Everything is organized into understandable folders and meticulously key tagged. Sound Designers \'ve added in Soundminer metadata into the samples to help you find the find right sound at the right time.</div>\r\n<div>&nbsp;</div>\r\n<div>All files are Royalty-Free and supplied to you in high quality 24-Bit WAV format that can be used in the most popular samplers, DAWs, and plugins with Drag and Drop plugin features.</div>\r\n<p style=\"font-stretch: normal; line-height: normal;\">&nbsp;</p>\r\n</div>', 0.00, 'ZIP', '', 'https://drive.google.com/file/d/1bJtRRekv8mrlgGu2VpApPErW0iihObED/view?usp=sharing', 'uploads/thumbnails/68d85665229ff_InfinityHipHopDrums_Vol2_Cover.webp', 'Commercial', '17 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/50135/Infinity%20Drums%20Vol.%202%20%20%20Demo%201.mp3', 'https://www.producerloops.com/Download-Epic-Stock-Media-Infinity-Hip-Hop-Drums-Vol-2.html', 1, 0, '2025-09-27 18:25:57', '2025-10-09 05:25:10', NULL),
(135, 38, NULL, 'Djay Pro 5 v5.4.4 macOS', 'djay-pro-5-v5-4-4-macos', '<p>Welcome to djay Pro! Algoriddim&rsquo;s acclaimed DJ software and winner of the Apple Design Award is built from the ground up for Mac. Connect your Spotify or Apple Music account to access millions of songs instantly and mix your favorite music. Whether you&rsquo;re a beginner or a seasoned DJ, djay Pro gives you everything you need to mix, perform, and build DJ sets with endless creativity.&nbsp;</p>', 4900.00, 'ZIP', '', 'https://drive.google.com/file/d/1tdPoRjyDcipl0nPiMGqpiH1QGUGFOCKI/view?usp=drive_link', 'uploads/thumbnails/68e78adf14a33_djay-Pro-AI-3-v3.0.1-macOS-TNT.jpg', 'Commercial', '755 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', NULL, '', 1, 0, '2025-10-09 10:13:51', '2025-10-09 10:13:51', NULL),
(136, 41, NULL, 'Reggae X Pop', 'reggae-x-pop', '<div><strong>course Details:</strong></div>\r\n<div>&nbsp;</div>\r\n<div>&bull; 5 Construction Kits</div>\r\n<div>&bull; 5 WAV Full Mixes Demos</div>\r\n<div>&bull; 5 MIDI Files Included</div>\r\n<div>&bull; All Loops include Dry &amp; Wet Versions</div>\r\n<div>&bull; 10 Drum Loops</div>\r\n<div>&bull; 10 Dub Drum Loops</div>\r\n<div>&bull; 24 Kick Loops</div>\r\n<div>&bull; 10 Rim Shot Loops</div>\r\n<div>&bull; 4 Clap Loops</div>\r\n<div>&bull; 12 Snare Loops</div>\r\n<div>&bull; 10 Hi-Hat Loops</div>\r\n<div>&bull; 2 Snap Loops</div>\r\n<div>&bull; 8 Cymbal Loops</div>\r\n<div>&bull; 4 Bass Loops</div>\r\n<div>&bull; 14 Synth Bass Loops</div>\r\n<div>&bull; 4 Bass 808 Loops</div>\r\n<div>&bull; 12 Perc Loops</div>\r\n<div>&bull; 52 Synth Loops</div>\r\n<div>&bull; 12 Piano Loops</div>\r\n<div>&bull; 2 Guitar Electric Loops</div>\r\n<div>&bull; 2 Brass Hits</div>\r\n<div>&bull; 4 Organ loops</div>\r\n<div>&bull;10 Timbales Fill</div>\r\n<div>&bull; 6 FXs</div>\r\n<div>&bull; 48kHz/24-Bit Quality</div>\r\n<div>&bull; Tempo Labelled</div>\r\n<div>&bull; 89-105 BPM</div>\r\n<div>&bull; 222 Files in Total</div>\r\n<div>&bull; 100% Royalty-Free</div>\r\n<div>\r\n<p class=\"lead\">\'Reggae X Pop\' from Kryptic Samples is an exquisite collection of Jamaican Reggae music and Modern Pop music samples. Delicately crafted by Kryptic, this pack will provide you with Reggae &amp; Dub drenched samples mingled with the sound of Pop music.</p>\r\n<div>&nbsp;</div>\r\n<div>This pack includes five Reggae &amp; Pop Construction Kits, featuring a far-ranging list of elements that includes a wide spectrum of Reggae &amp; Pop Music, hard-knocking 808, grooving modern Reggae drum loops and more. MIDI files are included so these samples are ready to be chopped, sliced, stretched and pitched.</div>\r\n</div>', 5200.00, 'ZIP', '', 'https://drive.google.com/file/d/1DHshZMiTBOKttgJU3u-0jmCHgQft2S3h/view?usp=sharing', 'uploads/thumbnails/68e78f416ea0a_Kryptic Samples-Reggae X Pop (800x800).webp', 'Commercial', '563 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/41964/Kryptic%20Samples%20Reggae%20X%20Pop%20%28Demo%29.mp3', 'https://www.producerloops.com/Download-Kryptic-Samples-Reggae-X-Pop.html', 1, 0, '2025-10-09 10:32:33', '2025-10-09 10:35:10', NULL),
(137, 41, NULL, 'Reggae Guitars', 'reggae-guitars', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 32 Guitar Loops<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p><strong>Introducing our Reggae Sample Pack featuring the iconic Fender Stratocaster American Deluxe. Immerse yourself in the rhythmic vibrations of reggae with authentic chord progressions and soulful riffs. The pack captures the essence of the genre, delivering the unmistakable sound of the Fender Stratocaster, renowned for its crisp, clean tones. Whether you\'re a seasoned reggae producer or exploring the genre for the first time, this pack provides essential tools to infuse your music with the laid-back grooves and vibrant energy of reggae. Elevate your sound with genuine chord voicings and infectious riffs, and let the Fender Stratocaster American Deluxe bring the soulful spirit of reggae to your courseions.</strong></p>', 1800.00, 'ZIP', '', 'https://drive.google.com/file/d/1aLPMjxVPse0DvgqDGHVJLJSIE6wOWNY-/view?usp=sharing', 'uploads/thumbnails/68e792122eda8_Reggae Guitas.webp', 'Commercial', '31 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/63835/Reggae%20Demo.mp3', 'https://www.producerloops.com/Download-38-Live-Vibes-Reggae-Guitars.html', 1, 0, '2025-10-09 10:44:34', '2025-10-09 10:45:42', NULL),
(138, 41, NULL, 'Reggae Riddims', 'reggae-riddims', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 10 Construction Kits featuring:<br>&bull; 101 WAV Loops<br>&bull; 81 MIDI Files</p>\r\n<p class=\"lead\"><strong>Deep Data Loops returns to Reggae music with these 10 construction kits featuring WAV &amp; MIDI Loops. Inside you\'ll find different Reggae styles from Roots to Dancehall with accordingly typical instrumentation from accoustic drums, guitars, brass, organ to synthesizers and drum machines. </strong></p>\r\n<p>The kits are also great for Dub Reggae if you apply / arrange your favourite delay effects. Single loops can inspire ideas for new songs as well. The given MIDI files let you exchange all sounds to be coming from your favoutire sources.</p>\r\n<p>You can exchange the sounds to be coming from your favourite (Digital or analog) synth by using the given MIDI files in this pack. This course is carefully handcrafted for your best producing experience and best possible entertainment. Put together some of these loops or get inspired by single ones and add your own flavor to complete your courseions.</p>', 4900.00, 'ZIP', '', 'https://drive.google.com/file/d/1k9aA0VEcws8K0OWFZCKTK2Ie0Ja2XYO8/view?usp=sharing', 'uploads/thumbnails/68e793ee63107_DDL255-Cover.webp', 'Commercial', '289 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/59486/Reggae%20Riddims.mp3', 'https://www.producerloops.com/Download-Deep-Data-Loops-Reggae-Riddims.html', 1, 0, '2025-10-09 10:52:30', '2025-10-09 10:53:15', NULL),
(139, 40, NULL, 'Hip Hop Plug', 'hip-hop-plug', '<div><strong>course Details:</strong></div>\r\n<div>&nbsp;</div>\r\n<div>5 Construction kits</div>\r\n<div>52 WAV Loops</div>\r\n<div>5 MIDI Stem Folders</div>\r\n<div>Key &amp; Tempo Labelled</div>\r\n<div>100% Royalty Free</div>\r\n<div>\r\n<p class=\"lead\">\'Hip Hop Plug\' by Studio Trap features 5 Trap and Hip Hop construction kits influenced by the likes of Gunna, Lil Baby, Roddy Ricch, Travis Scott, Future and more.</p>\r\n<div>&nbsp;</div>\r\n<div>This pack has everything you need to keep you ahead of the trend bringing you only the freshest and most up-to-date sounds for your music courseion guaranteed to squash your competition.</div>\r\n<div>&nbsp;</div>\r\n<div>All sounds have been processed and edited using professional outboard gear to ensure authentic analogue warmth. Just drag and drop the WAV files into your favorite DAW and you\'re good to go.</div>\r\n<div>&nbsp;</div>\r\n</div>', 2500.00, 'ZIP', '', 'https://drive.google.com/file/d/1oVDpoVJ3E6pz3dKNJE9iQioBkTCPem0G/view?usp=sharing', 'uploads/thumbnails/68e7dc6510b28_Hip Hop Plug 800x800.webp', 'Commercial', '41 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/49809/Hip%20Hop%20Plug%20Demo.mp3', 'https://www.producerloops.com/Download-Studio-Trap-Hip-Hop-Plug.html', 1, 0, '2025-10-09 16:01:41', '2025-10-09 16:02:19', NULL),
(140, 40, NULL, 'Hip Hop Strings Vol 1', 'hip-hop-strings-vol-1', '<p><strong>Features:</strong><br><br>&bull; All parts are individually exported<br>&bull; All loops are royalty-free<br>&bull; Keys and tempos are included</p>\r\n<div style=\"font-family: Arial,Verdana,sans-serif; font-size: 12px; color: rgb(34, 34, 34); background-color: rgb(255, 255, 255);\">\r\n<p class=\"lead\">\'Hip Hop Strings Vol 1\' is a heart-stopping series that brings you Orchestral String elements suitable for Hip Hop Producers. This course was designed to inspire the hidden Mozart in your courseions. With these 10 royalty-free kits you will be well on your way to making your next hit.</p>\r\n</div>\r\n<p><br>Everything you need is included in this set of Construction Kits. Our producers have carefully crafted rich string elements with a Hip Hop swagg that allow you to add a wide range of Orchestral tones to your courseions.</p>', 3800.00, 'ZIP', '', 'https://drive.google.com/file/d/14PNp5exQvQogLzzIJqi3E_ONwso0zjoE/view?usp=sharing', 'uploads/thumbnails/68e7deb66901d_Hip-Hop-strings(500)1-big.jpg', 'Commercial', '195 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/19355/Hip%20Hop%20Strings%20Vol%201%20Demo.mp3', 'https://www.producerloops.com/Download-The-Hit-Sound-Hip-Hop-Strings-Vol-1.html', 1, 0, '2025-10-09 16:11:34', '2025-10-09 16:12:18', NULL),
(141, 40, NULL, 'Colors: Hip Hop Trap Samples', 'colors-hip-hop-trap-samples', '<p><strong>Colors is a collection of 29 samples that are intended to build Hip Hop, Trap music.</strong></p>\r\n<p>The sample pack consists of carefully prepared samples of instruments such as Piano, Guitar, Acoustic Guitar, Keys, Bell . This library was inspired by top musicians, including Travis Scott, Lil Uzi Vert, Lil Baby, Gunna. All samples are licensed as Royalty-Free for you to use in your commercial courseions or even for DJ/Remix purposes. Spark your creativity with Colors from Major Loops and give your unfinished tracks exactly what they need to come back to life. This kit is perfect for beginners or well established producers looking to work with something different.</p>', 2300.00, 'ZIP', '', 'https://drive.google.com/file/d/1XBvFiYAM1ymfS6wZK3v9I9ps1VtStd5P/view?usp=sharing', 'uploads/thumbnails/68e7e2e9e27e9_Colors-Hip-Hop-Trap-Samples-WAV-FANTASTiC-MaGeSY.webp', 'Commercial', '220 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.slooply.com/public/demo-mp3/5e7720fdb30c6.mp3', 'https://slooply.com/sample-pack/colors', 1, 0, '2025-10-09 16:29:29', '2025-10-09 16:30:09', NULL),
(142, 25, NULL, 'FL Studio Producer 25.1.6  All Plugins + FLEX Bundle', 'fl-studio-producer-25-1-6-all-plugins-flex-bundle', '<p style=\"text-align: center;\">FL Studio is a complete software music courseion environment or Digital Audio Workstation (DAW). Representing more than 20 years of innovative development it has everything you need in one package to compose, arrange, record, edit, mix and master professional quality music.</p>\r\n<p style=\"text-align: center;\"><span id=\"more-254321\"></span></p>\r\n<p><span style=\"color: #c40c0c;\"><strong>The Mixer</strong></span><br>Mix and master music to the highest professional standards. All the features you need to create today&rsquo;s most complex courseions including, effects chains, audio sends, sidechain control, advanced automation, plugin delay compensation and more&hellip;</p>\r\n<p><span style=\"color: #c40c0c;\"><strong>Piano Roll</strong></span><br>FL Studio&rsquo;s Piano roll has the well deserved reputation as the best Piano roll in the business. The Piano roll is used to send note and automation data to plugin instruments (sequencing). It includes a wide range of tools to aid complex score editing and manipulation.</p>\r\n<p><span style=\"color: #c40c0c;\"><strong>Browser and Playlist</strong></span><br>No other DAW matches the flexibility of FL Studio&rsquo;s Playlist. Sequence all elements of the project to make the final song. Tracks can hold notes, audio and automation. Place any data type anywhere and even overlay them. Use the Browser to organize all the data in your project. Free your workflow and your mind!</p>\r\n<p><span style=\"color: #c40c0c;\"><strong>Over 80 plugins included</strong></span><br>FL Studio Producer Edition includes over 80 instrument and effect plugins covering automation, sample playback/manipulation, synthesis, compression, delay, equalization filtering, flanging, phasing, chorus, reverb, distortion, bit-crushing and more. With FL Studio you will be ready to create just about any style.</p>\r\n<p><span style=\"color: #c40c0c;\"><strong>Instruments &amp; FX</strong></span><br>If the huge array of native instruments and effects are not enough for you, FL Studio supports all VST standards 1, 2 and 3. VST gives you access to the wisest range of 3rd party plugins currently available. You can even use FL Studio itself as a VST plugin in another VST host.</p>', 5200.00, 'ZIP', '', 'https://drive.google.com/drive/folders/1Fk-uE5enx58W05qOdmfzb3VVJrYEU8K1?usp=sharing', 'uploads/thumbnails/68ea4e8cc6bc5_FL-Studio-Producer-Edition-v24.2-MaGeSY.webp', 'Commercial', '15 GB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', NULL, '', 1, 0, '2025-10-11 12:33:16', '2025-10-11 12:33:16', NULL),
(143, 37, NULL, 'Winds of Trap', 'winds-of-trap', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 330+ WAV Loops:<br>&bull; 30 Unique Flute Loops<br>&bull; 108 Extra Melody Loops (808s, Guitars, Bass, Brass, Strings, Keys&hellip;)<br>&bull; 194 Drum &amp; Percussion Loops<br>&bull; 80+ MIDI Files<br>&bull; 140+ One Shots:<br>&bull; 20 808s<br>&bull; 10 Kicks<br>&bull; 43 Snares, Claps &amp; Rims<br>&bull; 70 Hats &amp; Percussion<br>&bull; 100% Royalty-Free<br>&bull; 24-Bit WAV<br>&bull; Key &amp; Tempo Labelled</p>\r\n<p class=\"lead\"><strong>\'Winds of Trap\' by Shobeats is an All-In-One Sample Pack loaded with 550+ Files in Total, including 330+ WAV Loops, 80+ MIDI Files, and 140+ One-Shots to give you a saucy collection of Flute &amp; Guitar samples with matching Drums, 808s, Pads and more perfect for a Trap Music hit making.</strong></p>\r\n<p>This pack will provide you with must-have samples to help you produce your next hit track, including authentic real-world instruments. Every minute tone, nuance and outward breath has been captured with immense clarity &ndash; bringing a melodic high and effortless air to your courseions.</p>\r\n<p>MIDI files are included so you can control your project completely. The MIDI files allow you to apply the melodies to any sound. Alternatively, Drag and Drop the WAV files into your DAW of choice to get started on your next track.</p>\r\n<p>Inside, you\'ll also find One-Shots, allowing you to create new beats, fills, and loops to complement the existing material. Load them up into your sampler of choice and create an infinite number of Drum Loops.</p>\r\n<p>And, of course, all Loops &amp; Samples are 100% Royalty-Free!</p>', 3800.00, 'ZIP', '', 'https://drive.google.com/file/d/1yHZkdrXJv4VdfTmIDR77L1SJ_Mgqji1w/view?usp=sharing', 'uploads/thumbnails/68eb5e3b896d5_winds-of-trap-Cover-x.webp', 'Commercial', '648 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/58659/winds%20of%20trap%20bundle.mp3', 'https://www.producerloops.com/Download-Shobeats-Winds-of-Trap.html', 1, 0, '2025-10-12 07:52:27', '2025-10-12 07:55:03', NULL),
(144, 34, NULL, 'Afro Genesis Vol 2', 'afro-genesis-vol-2', '<p><strong>course Details:</strong></p>\r\n<p>&bull; 94 WAV Loops (Including Drums, Melodics)<br>&bull; 24 MIDI Files<br>&bull; 31 One-Shots<br>&bull; 44.1kHz/24-Bit WAV Quality<br>&bull; Key &amp; Tempo Labelled<br>&bull; 100% Royalty-Free</p>\r\n<p class=\"lead\"><strong>\'Afro Genesis Vol. 2\' by Dik3l is an All-In-One sample pack loaded with 94 WAV loops, 24 MIDI files, and 31 one-shots, A collection of sounds intended to build Afrobeats, Afro Swing, and Afro RnB music, equipped with the essential kits and tools to create smashing Afrohits!</strong></p>\r\n<p>MIDI files are included so you can control your project thoroughly. The MIDI files allow you to apply the melodies to any sound. Alternatively, Drag and Drop the WAV files into your DAW of choice to get started on your next track.</p>', 3200.00, 'ZIP', '', 'https://drive.google.com/file/d/1udQQxQYVgJHjkUjbM99SGAKvUwZBjndw/view?usp=sharing', 'uploads/thumbnails/68ec8974907bc_AfroGenesisVol.2All-In-Onecover.webp', 'Commercial', '90 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', 'https://cdn.producerloops.com/files/audio/67756/Afro%20Genesis%20Vol.%202%20%28All%20In%20One%29%20demo.mp3', 'https://www.producerloops.com/Download-Dik3l-Sounds-Afro-Genesis-Vol-2.html', 1, 0, '2025-10-13 05:09:08', '2025-10-13 05:09:21', NULL),
(145, 29, NULL, '\"Alone\" FL STUDIO Vocal Chain Preset', 'alone-fl-studio-vocal-chain-preset', '<p>&nbsp;</p>\r\n<p><strong>Item Description</strong></p>\r\n<ul>\r\n<li>ALL FLP Stock Plugins</li>\r\n<li>Instant File Download After Purchase</li>\r\n<li>Works with FL Studio&nbsp;<strong>12.5</strong><strong>+</strong></li>\r\n<li>Easy Install Instructions document</li>\r\n<li><strong>2</strong>&nbsp;Preset Inserts</li>\r\n<li><strong>18</strong>&nbsp;Individual STOCK Plugins</li>\r\n<li><strong>1</strong> FL Studio Starter Template</li>\r\n<li>Video on how to find key scale to beat</li>\r\n<li>Supports Windows and Mac Operating Systems</li>\r\n</ul>', 3500.00, 'ZIP', '', 'https://drive.google.com/file/d/175jewfzRypJYM58sROqSHSdyryp58QqA/view?usp=sharing', 'uploads/thumbnails/690ce4b10063c_WhatsApp Image 2025-11-06 at 14.14.01.jpeg', 'Commercial', '1 MB', 'AK23STUDIOKITS', 'ak23studiokits.com', '', '', 'https://keywav.io/courses/bryson-tiller-type-fl-studio-vocal-chain-preset', 1, 0, '2025-10-15 17:49:30', '2025-11-06 18:10:57', NULL);

